package com.axplatform.sheet;

import com.axplatform.common.*;
import com.axplatform.policy.AccessService;
import com.axplatform.security.SessionSubject;
import com.axplatform.workspace.DraftService;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.springframework.stereotype.Service;

@Service
public class DataCenterService {
 private final SheetService sheets;private final DraftService drafts;private final AccessService access;
 public DataCenterService(SheetService sheets,DraftService drafts,AccessService access){this.sheets=sheets;this.drafts=drafts;this.access=access;}
 private <T>T allowed(SessionSubject actor,String id,List<String> actions,java.util.function.Supplier<T> fn){var draft=drafts.get(actor,id);return access.business(actor,Inputs.number(draft,"business_scope_id"),false,actions,fn);}
 @SuppressWarnings("unchecked") public Map<String,Object> data(SessionSubject actor,String id,Map<String,Object> raw,int page,boolean profile){var config=DataReport.config(raw);return allowed(actor,id,config.get("mode").equals("REPORT")?List.of("workspace.sheet.read","workspace.sheet.analysis.read"):List.of("workspace.sheet.read"),()->{var snapshot=sheets.getSheet(actor,id,(String)config.get("sheetId"));if(Inputs.number(snapshot,"version")<0)throw Problem.invalid("저장된 표가 없습니다. 편집에서 먼저 저장하세요.");var table=(Map<String,Object>)snapshot.get("sheet");var result=DataReport.page(DataReport.build(table,config),page,Inputs.number(snapshot,"version"));result.put("draftVersion",snapshot.get("draftVersion"));if(profile)result.put("profile",DataReport.profile(table));return result;});}
 @SuppressWarnings("unchecked") public Map<String,Object> column(SessionSubject actor,String id,Map<String,Object> spec,long version,long draftVersion,boolean apply,boolean acceptErrors){return allowed(actor,id,List.of("workspace.sheet.read","workspace.sheet.update","workspace.sheet.schema.update","workspace.sheet.formula.update","workspace.draft.update"),()->{var snap=sheets.get(actor,id);if(Inputs.number(snap,"version")!=version||Inputs.number(snap,"draftVersion")!=draftVersion)throw Problem.conflict("기준 데이터가 바뀌었습니다. 최신 데이터를 불러오고 계산 열을 다시 미리보기 하세요.");if("ARCHIVED".equals(drafts.get(actor,id).get("status")))throw Problem.invalid("보관된 업무는 먼저 복원하세요.");var book=CalculatedColumn.build((Map<String,Object>)snap.get("workbook"),spec);var preview=CalculatedColumn.preview(book,DataReport.str(spec,"sheetId","sheet1"),version,draftVersion);if(!apply)return preview;if(Inputs.number(preview,"errorCount")>0&&!acceptErrors)throw Problem.invalid("계산 오류가 있는 행을 확인하고 ‘오류를 표시한 채 추가’를 선택하세요.");return sheets.putWorkbook(actor,id,book,version,draftVersion);});}
 public void checkExport(SessionSubject actor,String id,Map<String,Object> config){allowed(actor,id,"REPORT".equals(config.get("mode"))?List.of("workspace.sheet.read","workspace.sheet.export","workspace.sheet.analysis.read"):List.of("workspace.sheet.read","workspace.sheet.export"),()->null);}
 @SuppressWarnings("unchecked") public SheetService.Export export(SessionSubject actor,String id,Map<String,Object> raw,String format,long version){var config=DataReport.config(raw);if(!Set.of("xlsx","csv").contains(format))throw Problem.invalid("다운로드 형식을 확인하세요.");return allowed(actor,id,config.get("mode").equals("REPORT")?List.of("workspace.sheet.export","workspace.sheet.analysis.read"):List.of("workspace.sheet.export"),()->{var snap=sheets.getSheet(actor,id,(String)config.get("sheetId"));if(Inputs.number(snap,"version")!=version)throw Problem.conflict("데이터가 바뀌었습니다. 현재 보기를 새로고침하고 다운로드하세요.");var result=DataReport.build((Map<String,Object>)snap.get("sheet"),config);String name=config.get("name").toString().replaceAll("[\\p{Cntrl}\\\\/:*?\"<>|]","_");try{byte[] bytes;if(format.equals("csv")){var out=new StringBuilder("\ufeff");out.append(csv(result.columns().stream().map(c->c.get("label").toString()).toList()));for(var row:result.rows())out.append(csv(row));bytes=out.toString().getBytes(StandardCharsets.UTF_8);}else{var cols=result.columns().stream().map(c->{var m=new LinkedHashMap<String,Object>();for(String key:List.of("id","label","type","unit","width","format","decimals"))if(c.containsKey(key))m.put(key,c.get(key));m.putIfAbsent("unit","");m.putIfAbsent("width",160);return m;}).toList();for(int ci=0;ci<cols.size();ci++){final int at=ci;if("NUMBER".equals(cols.get(ci).get("type"))&&result.rows().stream().anyMatch(r->!r.get(at).isEmpty()&&DataReport.number(r.get(at))==null))cols.get(ci).put("type","TEXT");}var table=new LinkedHashMap<String,Object>();table.put("columns",cols);table.put("rows",result.rows());table.put("rowIds",java.util.stream.IntStream.range(0,result.rows().size()).mapToObj(i->"r_"+i).toList());bytes=XlsxWriter.workbookBytes(WorkbookRules.normalize(table));}return new SheetService.Export(name+"."+format,bytes,version);}catch(java.io.IOException ex){throw new Problem(503,"EXPORT_FAILED","현재 보기 파일을 만들지 못했습니다.");}});}
 private static String csv(List<String> row){return row.stream().map(v->{String safe=v.matches("(?s)^[=+@\\t\\r\\n].*")||v.startsWith("-")&&DataReport.number(v)==null?"'"+v:v;return "\""+safe.replace("\"","\"\"")+"\"";}).collect(java.util.stream.Collectors.joining(","))+"\r\n";}
}
